function watchtowerPlacements(size) {
    const columns = Array.from({ length: size }, (_, i) => i);
    let count = 0;
    function safe(assignment) {
        for (let a = 0; a < assignment.length; a++)
            for (let b = a + 1; b < assignment.length; b++)
                if (Math.abs(assignment[a] - assignment[b]) === b - a)
                    return false;
        return true;
    }
    function permute(prefix, remaining) {
        if (remaining.length === 0) {
            if (safe(prefix))
                count++;
            return;
        }
        for (let i = 0; i < remaining.length; i++)
            permute([...prefix, remaining[i]], [...remaining.slice(0, i), ...remaining.slice(i + 1)]);
    }
    permute([], columns);
    return count;
}

function watchtowerPlacements(size) {
    const usedColumns = new Set();
    const usedRising = new Set();
    const usedFalling = new Set();
    function place(row) {
        if (row === size)
            return 1;
        let total = 0;
        for (let column = 0; column < size; column++) {
            if (usedColumns.has(column) || usedRising.has(row + column) || usedFalling.has(row - column))
                continue;
            usedColumns.add(column);
            usedRising.add(row + column);
            usedFalling.add(row - column);
            total += place(row + 1);
            usedColumns.delete(column);
            usedRising.delete(row + column);
            usedFalling.delete(row - column);
        }
        return total;
    }
    return place(0);
}
